import{_ as t,c as r,o as n,aS as o}from"./chunks/framework.BItddkxz.js";const c=JSON.parse('{"title":"谢凯新","description":"","frontmatter":{},"headers":[],"relativePath":"about/index.md","filePath":"about/index.md","lastUpdated":1772792710000}'),s={name:"about/index.md"},g=o('<h1 id="谢凯新" tabindex="-1">谢凯新 <a class="header-anchor" href="#谢凯新" aria-label="Permalink to &quot;谢凯新&quot;">​</a></h1><p><strong>AI增强型项目经理 | PMP®认证 | 全栈交付专家</strong> 📞 136-3140-7919 | 📧 <a href="mailto:bongxin@yeah.net" target="_blank" rel="noreferrer">bongxin@yeah.net</a> | 📍 广州</p><hr><h3 id="🚀-核心价值-ai赋能的效能革命" tabindex="-1">🚀 核心价值：AI赋能的效能革命 <a class="header-anchor" href="#🚀-核心价值-ai赋能的效能革命" aria-label="Permalink to &quot;🚀 核心价值：AI赋能的效能革命&quot;">​</a></h3><ul><li><strong>AI驱动的全栈交付</strong>：打破传统PM与开发的边界。深度整合 <strong>Cursor</strong> (AI代码编辑器) 与 <strong>通义千问</strong> (大模型) 至工作流，具备独立快速构建原型、编写核心代码及自动化测试的能力。在近期项目中，利用AI辅助将<strong>开发效率提升50%</strong>，实现“需求-设计-代码-文档”的极速闭环。</li><li><strong>设计思维可视化 <strong>(Figma)：摒弃传统的文字需求文档，精通 <strong>Figma</strong> 高保真原型设计。能在现场调研时直接绘制可交互原型，将“需求确认”时间从数天缩短至</strong>小时级</strong>，大幅降低沟通成本与返工风险。(现在更多采用AI直接生成页面的方式)</li><li><strong>专家级文档与汇报</strong>：擅长利用AI工具辅助撰写高质量的<strong>招投标方案、技术白皮书及汇报PPT</strong>。能够快速梳理复杂逻辑，生成结构严谨、视觉专业的文档，多次在百万级项目竞标中凭借优异方案胜出。</li><li><strong>现场交付与需求洞察</strong>：拥有极强的驻场实战经验。善于在复杂现场环境中，结合<strong>AI数据分析</strong>与<strong>引导式提问</strong>，精准挖掘客户隐性需求，并迅速转化为可落地的技术方案。</li></ul><hr><h3 id="💼-工作经历" tabindex="-1">💼 工作经历 <a class="header-anchor" href="#💼-工作经历" aria-label="Permalink to &quot;💼 工作经历&quot;">​</a></h3><p><strong>广州华微明天软件技术有限公司</strong> | 2018.08 – 至今 <strong>职位</strong>：项目经理 / AI效能实践者 <strong>核心职责</strong>：</p><ul><li><strong>AI工作流重构</strong>：在团队内推广 <strong>Cursor</strong> 编程助手，建立“自然语言描述 -&gt; AI生成代码框架 -&gt; 人工审查优化”的开发模式。个人常利用此模式在关键节点<strong>独立承担</strong>核心模块开发，减少对纯开发资源的依赖。</li><li><strong>设计与交付闭环</strong>：主导项目从0到1的孵化。利用 <strong>Figma</strong> 快速输出高保真UI/UX，直接指导前端还原；利用 <strong>通义千问</strong> 自动生成单元测试用例、用户手册及API文档，确保交付物标准化且高质量。</li><li><strong>商务与方案支撑</strong>：负责招投标技术标书撰写及现场述标PPT制作。通过AI辅助分析招标文件痛点，定制化输出解决方案。</li></ul><p><strong>广州思迈特软件有限公司</strong> | 2016.08 – 2018.07 <strong>职位</strong>：定制开发工程师 <strong>主要职责</strong>：负责电信及企业定制化项目的全栈开发，奠定了扎实的技术底座，为后续驾驭AI编程工具打下坚实基础。</p><hr><h3 id="🏆-重点项目经验-ai赋能实战" tabindex="-1">🏆 重点项目经验（AI赋能实战） <a class="header-anchor" href="#🏆-重点项目经验-ai赋能实战" aria-label="Permalink to &quot;🏆 重点项目经验（AI赋能实战）&quot;">​</a></h3><h4 id="_1-智慧农业与食品溯源系列-2021-10-–-至今" tabindex="-1">1. 智慧农业与食品溯源系列（2021.10 – 至今） <a class="header-anchor" href="#_1-智慧农业与食品溯源系列-2021-10-–-至今" aria-label="Permalink to &quot;1. 智慧农业与食品溯源系列（2021.10 – 至今）&quot;">​</a></h4><p><strong>角色</strong>：项目经理 &amp; 核心架构师</p><ul><li><p><strong>中山颐丰智慧屠宰项目</strong> (2024.10)</p><ul><li><strong>AI提效</strong>：利用 <strong>Cursor</strong> 快速搭建物联网数据接收中间件，将原本需3天的接口开发压缩至<strong>0.5天</strong>；使用 <strong>通义千问</strong> 生成设备接入规范文档。</li><li><strong>设计落地</strong>：现场使用 <strong>Figma</strong> 绘制屠宰流程监控大屏原型，当场获得甲方确认，避免后期需求变更。</li><li><strong>成果</strong>：项目提前2周上线，实现全流程数字化追溯。</li></ul></li><li><p><strong>贵州移动AI问答项目</strong> (2024.08)</p><ul><li><strong>核心职责</strong>：主导基于大模型的智能客服系统落地。</li><li><strong>AI实践</strong>：作为项目核心，直接利用 <strong>Prompt Engineering</strong> 优化模型回答准确率，协助团队清洗训练数据，展现了对AI技术的深度理解与应用能力。</li><li><strong>成果</strong>：快速迭代多个版本，显著降低人工客服压力，获甲方高度认可。</li></ul></li><li><p><strong>粤海食品智慧屠宰/销售系统</strong> (2021.10 – 2023.09)</p><ul><li><strong>需求与交付</strong>：深入一线猪场与屠宰场，通过“<strong>现场访谈 + Figma原型演示</strong>”的方式，将模糊的业务痛点转化为清晰的功能列表。</li><li><strong>文档能力</strong>：独立撰写全套《用户需求说明书》与《系统操作手册》，并利用AI工具将其转化为视频教程脚本，极大提升了用户培训效率。</li><li><strong>成果</strong>：成功中标二期项目，客户满意度评级为“优秀”。</li></ul></li></ul><h4 id="_2-智慧水务与政府信息化系列-2018-08-–-2022-12" tabindex="-1">2. 智慧水务与政府信息化系列（2018.08 – 2022.12） <a class="header-anchor" href="#_2-智慧水务与政府信息化系列-2018-08-–-2022-12" aria-label="Permalink to &quot;2. 智慧水务与政府信息化系列（2018.08 – 2022.12）&quot;">​</a></h4><p><strong>角色</strong>：项目负责人 (PL) &amp; 主设计师</p><ul><li><p><strong>白云智慧水务项目</strong> (2022.12)</p><ul><li><strong>方案设计</strong>：负责整体技术架构设计与PPT汇报材料制作。利用AI辅助分析历史水务数据，提出预测性维护方案，在评标中获得高分。</li><li><strong>可视化</strong>：使用 <strong>Figma</strong> 设计水务驾驶舱界面，直观展示水质水量监测数据，成为项目亮点。</li></ul></li><li><p><strong>东江北干流大墩国考断面达标系统</strong> (2019.11 – 2020.04)</p><ul><li><strong>驻场攻坚</strong>：作为驻场负责人，面对工期紧、需求变更多的挑战，采用“<strong>白天调研画原型（Figma），晚上AI辅助写代码/文档</strong>”的高强度模式。</li><li><strong>成果</strong>：按期高质量交付，并成功促成后续<strong>500万+运维合同</strong>的签订，证明了极强的现场把控与商业转化能力。</li></ul></li><li><p><strong>东江流域水资源监测体系深化建设</strong> (2020.09)</p><ul><li><strong>技术落地</strong>：主导前端重构，引入组件化开发思想，提升系统响应速度。</li></ul></li></ul><h4 id="_3-运营商与定制化项目" tabindex="-1">3. 运营商与定制化项目 <a class="header-anchor" href="#_3-运营商与定制化项目" aria-label="Permalink to &quot;3. 运营商与定制化项目&quot;">​</a></h4><ul><li><strong>长沙移动项目</strong> (2020.11 – 2022.04)：担任项目经理，统筹多方资源，确保复杂集成项目顺利验收。</li><li><strong>湖北电信定制项目</strong> (2018.05 – 2018.07)：<strong>独立全栈交付</strong>。在无后端支持情况下，独立完成前后端开发（此经历验证了您现在能驾驭AI辅助开发的潜力，如今效率已翻倍）。</li></ul><hr><h3 id="🛠-技能栈-传统实力-ai新引擎" tabindex="-1">🛠 技能栈：传统实力 + AI新引擎 <a class="header-anchor" href="#🛠-技能栈-传统实力-ai新引擎" aria-label="Permalink to &quot;🛠 技能栈：传统实力 + AI新引擎&quot;">​</a></h3><table><thead><tr><th style="text-align:left;">类别</th><th style="text-align:left;">核心技能</th><th style="text-align:left;"><strong>AI赋能下的应用场景</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>AI效能工具</strong></td><td style="text-align:left;"><strong>Cursor, 通义千问, Copilot</strong></td><td style="text-align:left;"><strong>代码</strong>：自动生成CRUD、正则、SQL、单元测试；<strong>文档</strong>：一键生成会议纪要、技术文档初稿、标书润色；<strong>决策</strong>：辅助风险分析与方案比对。</td></tr><tr><td style="text-align:left;"><strong>设计与原型</strong></td><td style="text-align:left;"><strong>Figma, Axure</strong></td><td style="text-align:left;"><strong>现场交付</strong>：实时绘制高保真交互原型，所见即所得；<strong>UI规范</strong>：快速生成设计系统（Design System），统一团队风格。</td></tr><tr><td style="text-align:left;"><strong>文档与汇报</strong></td><td style="text-align:left;"><strong>PPT</strong></td><td style="text-align:left;"><strong>投标/汇报</strong>：利用AI快速构建PPT大纲与内容，自动美化排版；<strong>方案书</strong>：快速输出几百页的技术方案书，确保逻辑严密。</td></tr><tr><td style="text-align:left;"><strong>项目管理</strong></td><td style="text-align:left;"><strong>PMP, 禅道, Project</strong></td><td style="text-align:left;">敏捷/瀑布混合管理、风险控制、干系人管理、成本/进度控制。</td></tr><tr><td style="text-align:left;"><strong>技术开发</strong></td><td style="text-align:left;"><strong>Vue.js, JS, 小程序</strong></td><td style="text-align:left;"><strong>技术评审</strong>：准确评估AI生成代码的质量与安全性；<strong>快速原型</strong>：独立搭建MVP（最小可行性产品）验证业务。</td></tr><tr><td style="text-align:left;"><strong>行业领域</strong></td><td style="text-align:left;"><strong>智慧农业（智慧屠宰）, 智慧水务</strong></td><td style="text-align:left;">熟悉业务流程、政策法规及行业标准，具备深厚的领域知识。</td></tr></tbody></table><hr><h3 id="🎓-教育背景" tabindex="-1">🎓 教育背景 <a class="header-anchor" href="#🎓-教育背景" aria-label="Permalink to &quot;🎓 教育背景&quot;">​</a></h3><ul><li><strong>2012.09 – 2016.06</strong> | <strong>广东药科大学</strong> | 计算机科学与技术 | 本科</li><li><strong>2024.06</strong> | <strong>PMP® 项目管理专业人士认证</strong></li></ul><hr>',27),l=[g];function e(a,i,d,h,u,f){return n(),r("div",null,l)}const p=t(s,[["render",e]]);export{c as __pageData,p as default};
